import{_ as s,C as r,c as n,o as i,a3 as t,G as a}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"My Time","description":"","frontmatter":{},"headers":[],"relativePath":"master/human-resources/time-off/requests/my-time.md","filePath":"master/human-resources/time-off/requests/my-time.md","lastUpdated":1791902625000}'),l={name:"master/human-resources/time-off/requests/my-time.md"};function d(h,e,m,f,g,u){const o=r("ImagePopup");return i(),n("div",null,[e[0]||(e[0]=t('<h1 id="my-time" tabindex="-1">My Time <a class="header-anchor" href="#my-time" aria-label="Permalink to &quot;My Time&quot;">​</a></h1><p>My Time is your personal Time Off page. It shows how many days you have left for each leave type, how many requests wait for a decision, and a calendar of your requests. You can also start a new request from here.</p><blockquote><p><strong>In simple words:</strong> Look here to see your balance and your booked days, then click a date to ask for time off.</p></blockquote><p>Menu: <code>Time Off → My Time → Dashboard</code>. The left sub-menu also has <strong>My Time off</strong> and <strong>My Allocation</strong>.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><p>Your user needs an employee record. Create it in <a href="./../../employees/">Employees</a>. Balances come from approved <a href="./../allocations/">allocations</a>.</p></div><h2 id="balance-cards" tabindex="-1">Balance cards <a class="header-anchor" href="#balance-cards" aria-label="Permalink to &quot;Balance cards&quot;">​</a></h2><p>The <strong>Time Off Analysis</strong> block shows one card per leave type that has <strong>Show on Dashboard</strong> turned on. Each card has the type name, your balance and <strong>Valid until</strong> with the end of the current year, for example <strong>Valid until 2026-12-31</strong>. Cards use the colour of the leave type.</p><p>Sarah Mitchell has <strong>Paid Time Off 20.0</strong> and <strong>0.0</strong> for the other types.</p>',8)),a(o,{src:"/images1/time-off/mytime_dashboard_cards.png",alt:"Time Off Analysis cards: Paid Time Off 20.0, the other leave types 0.0, each valid until 2026-12-31, and Pending Requests 0 with the line Time Off Requests"}),e[1]||(e[1]=t('<p>The last card, <strong>Pending Requests</strong>, counts your requests that are <strong>To Approve</strong>. It carries the line <strong>Time Off Requests</strong>. A request that waits for approval adds 1 here and also lowers the balance of its type at once.</p><p>Choose which types appear in <a href="./../setup/time-off-types.html">Time off types</a> with <strong>Show on Dashboard</strong>.</p><h2 id="calendar" tabindex="-1">Calendar <a class="header-anchor" href="#calendar" aria-label="Permalink to &quot;Calendar&quot;">​</a></h2><p>Below the cards is your calendar. It shows your own requests, coloured by leave type. A title shows the leave type, the name of the logged in user and the length, for example <strong>Paid Time Off ERP Admin (3d)</strong>. Here <strong>ERP Admin</strong> is the user name.</p><ul><li><strong>Toolbar:</strong> previous and next arrows, <strong>Today</strong>, and the title, for example <strong>October 2026</strong>.</li><li><strong>Views:</strong> <strong>Month</strong> (default), <strong>Week</strong> and <strong>List</strong>. The week starts on Monday and weekends are shaded.</li><li><strong>List view:</strong> shows <strong>No events to display</strong> when the week is empty.</li></ul>',5)),a(o,{src:"/images1/time-off/mytime_calendar_month.png",alt:"My Time calendar for October 2026 with a Paid Time Off ERP Admin (3d) bar from 19 to 21 October, the Holidays button, the New Time Off button, arrows, Today and the Month, Week and List buttons"}),e[2]||(e[2]=t('<h3 id="holidays-panel" tabindex="-1">Holidays panel <a class="header-anchor" href="#holidays-panel" aria-label="Permalink to &quot;Holidays panel&quot;">​</a></h3><p>Click the blue icon at the top right of the calendar, next to <strong>New Time Off</strong>. The <strong>Holidays</strong> panel slides in from the right with:</p><ul><li><strong>Public Holidays:</strong> names with dates, for example <strong>Gandhi Jayanti</strong> and <strong>Christmas Day</strong>.</li><li><strong>Mandatory Holidays:</strong> company days such as <strong>Company Anniversary</strong>, shown with the company name.</li></ul>',3)),a(o,{src:"/images1/time-off/mytime_holidays_window.png",alt:"Holidays panel on the right listing Public Holidays and Mandatory Holidays"}),e[3]||(e[3]=t('<p>Manage these lists in <a href="./../setup/public-holidays.html">Public holidays</a> and <a href="./../setup/mandatory-days.html">Mandatory days</a>.</p><h2 id="create-from-the-calendar" tabindex="-1">Create from the calendar <a class="header-anchor" href="#create-from-the-calendar" aria-label="Permalink to &quot;Create from the calendar&quot;">​</a></h2><ol><li>Click the green <strong>New Time Off</strong> button, or click a date.</li><li>A click on a date fills both date fields and shows <strong>Duration</strong> as <code>1 working day</code>.</li><li>Complete the form. See <a href="./request-time-off.html">Request time off</a>.</li></ol><h2 id="open-a-request" tabindex="-1">Open a request <a class="header-anchor" href="#open-a-request" aria-label="Permalink to &quot;Open a request&quot;">​</a></h2><p>Click an event on the calendar. The <strong>View</strong> window has the subtitle <strong>View Time Off Request</strong> and a <strong>Time Off Details</strong> section. It shows <strong>Time Off Type</strong>, <strong>Status</strong>, <strong>Request Date From</strong>, <strong>Request Date To</strong>, <strong>Duration</strong> (<code>3 working days</code>) and <strong>Description</strong>. It has three buttons.</p><ul><li><strong>Edit:</strong> (yellow button) change the request.</li><li><strong>Delete:</strong> remove it.</li><li><strong>Cancel:</strong> close the window.</li></ul>',6)),a(o,{src:"/images1/time-off/mytime_event_view.png",alt:"View window for the Paid Time Off request from October 19 to October 21, 2026, status To Approve, Duration 3 working days, description Family function, with Edit, Delete and Cancel buttons"}),e[4]||(e[4]=t('<h2 id="my-time-off-list" tabindex="-1">My Time off list <a class="header-anchor" href="#my-time-off-list" aria-label="Permalink to &quot;My Time off list&quot;">​</a></h2><p>Open <code>Time Off → My Time → My Time off</code>. The page is titled <strong>My Time Offs</strong>. Click <strong>New My Time off</strong> to start a request.</p><p>The list shows requests from all employees, including the new ones from this guide.</p><ul><li><strong>Columns:</strong> <strong>Employee</strong>, <strong>Time Off Type</strong>, <strong>Description</strong>, <strong>Date From</strong>, <strong>Date To</strong>, <strong>Duration</strong>, <strong>Status</strong>.</li><li><strong>Group by:</strong> Employee, Time Off Type, Status, Start Date, End Date.</li><li><strong>Search</strong> box and a <strong>Delete selected</strong> bulk action.</li></ul>',4)),a(o,{src:"/images1/time-off/mytime_my_time_off_list.png",alt:"My Time Offs list with 10 requests, including Sarah Mitchell 3 working days Approved, Priya Sharma 2 working days To Approve, a Refused Sick Time Off day and a 0.5 day half day with no Date To"}),e[5]||(e[5]=t('<h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./request-time-off.html">Request time off</a></li><li><a href="./manage-requests.html">Manage requests</a></li><li><a href="./overview-calendar.html">Overview calendar</a></li><li><a href="./">Time off requests</a></li></ul>',2))])}const y=s(l,[["render",d]]);export{p as __pageData,y as default};
